import java.util.*;

class DiagonalSum {
    static String diagonalSum(int[] values) {
        Integer[] copy = Arrays.stream(values).boxed().toArray(Integer[]::new);
        Arrays.sort(copy, Collections.reverseOrder());
        return Arrays.stream(copy).map(String::valueOf).reduce((left, right) -> left + "," + right).orElse("");
    }
}
